description:
`io.Framerate` is not the rate of the last frame, which jumps around: it averages the last frames. Write the same thing:

```cpp
class FrameRate
{
public:
    explicit FrameRate(int window);   // how many recent frames to average
    void add(double deltaSeconds);    // one frame's duration
    double fps() const;               // frames per second over the recent frames, 0 if none yet
    double averageMs() const;         // average frame time in milliseconds, 0 if none yet
};
```

`fps()` is the number of frames in the window divided by their total duration. Keep only the last `window` durations: when a new one arrives and the window is full, the oldest is dropped. Keep a running total rather than adding all durations up on every call.

starter.solution.cpp:
#include <vector>

class FrameRate
{
public:
    explicit FrameRate(int window) {}
    void add(double deltaSeconds) {}
    double fps() const { return 0.0; }
    double averageMs() const { return 0.0; }
};

solution.solution.cpp:
#include <vector>

class FrameRate
{
public:
    explicit FrameRate(int window) : m_samples(static_cast<std::size_t>(window < 1 ? 1 : window), 0.0) {}

    void add(double deltaSeconds)
    {
        if (m_count == m_samples.size()) m_total -= m_samples[m_next];
        else ++m_count;
        m_samples[m_next] = deltaSeconds;
        m_total += deltaSeconds;
        m_next = (m_next + 1) % m_samples.size();
    }

    double fps() const { return m_count && m_total > 0 ? static_cast<double>(m_count) / m_total : 0.0; }
    double averageMs() const { return m_count ? 1000.0 * m_total / static_cast<double>(m_count) : 0.0; }

private:
    std::vector<double> m_samples;
    std::size_t m_next{ 0 };
    std::size_t m_count{ 0 };
    double m_total{ 0.0 };
};

unitTests:
TEST("nothing yet") { FrameRate f{ 4 }; CHECK_NEAR(f.fps(), 0.0, 1e-9); CHECK_NEAR(f.averageMs(), 0.0, 1e-9); }
TEST("steady 60") { FrameRate f{ 10 }; for (int i = 0; i < 25; ++i) f.add(1.0 / 60.0); CHECK_NEAR(f.fps(), 60.0, 1e-6); CHECK_NEAR(f.averageMs(), 1000.0 / 60.0, 1e-6); }
TEST("only the last frames count") { FrameRate f{ 2 }; f.add(1.0); f.add(0.01); f.add(0.01); CHECK_NEAR(f.fps(), 100.0, 1e-6); }
TEST("a mix") { FrameRate f{ 4 }; f.add(0.010); f.add(0.020); f.add(0.030); f.add(0.040); CHECK_NEAR(f.averageMs(), 25.0, 1e-9); CHECK_NEAR(f.fps(), 40.0, 1e-9); }

